37	using ApplyOutputView = std::function<std::string(const std::string &var)>;
38	struct ViewPolicy {
39	 public:
40	  enum ViewType : int64_t {
41	    kElementWise = 0,
42	    kReduce,
43	    kBroadCast,
44	    kInvalid,
45	  };
46	  ViewPolicy(uint32_t element_wise_input_index) : use_input_index(element_wise_input_index) {
47	    view_type = kElementWise;
48	  }
49	  ViewPolicy(uint32_t reduce_input_index, std::string reduce_axis_name)
50	      : use_input_index(reduce_input_index), reduce_axis_attr_name(std::move(reduce_axis_name)) {
51	    view_type = kReduce;
52	  }
53	
54	  explicit ViewPolicy(std::vector<uint32_t> broad_cast_in_indexs)
55	      : broad_cast_input_indexs(std::move(broad_cast_in_indexs)) {
56	    view_type = kBroadCast;
57	  }
58	
59	  ViewType view_type{kInvalid};
60	  uint32_t use_input_index{UINT32_MAX};
61	  std::string reduce_axis_attr_name;
62	  std::vector<uint32_t> broad_cast_input_indexs;
63	};
64	
65	inline ViewPolicy ReduceView(uint32_t index, const std::string &attr_name) {
66	  return ViewPolicy(index, attr_name);
67	}
68	inline ViewPolicy BroadCastView(const std::vector<uint32_t> &broad_cast_input_indexs) {
69	  return ViewPolicy(broad_cast_input_indexs);
