72	struct DtypePolicy {
73	  enum PolicyType : int64_t {
74	    kUseInput = 0,
75	    kPromptInput,
76	    kUseDtype,
77	    kInvalid,
78	  };
79	
80	 public:
81	  DtypePolicy(uint32_t use_in_index) : use_input_index(use_in_index) {
82	    policy_type = kUseInput;
83	  };
84	  DtypePolicy(ge::DataType dtype) : data_type(dtype) {
85	    policy_type = kUseDtype;
86	  };
87	  PolicyType policy_type{kInvalid};
88	  uint32_t use_input_index{UINT32_MAX};
89	  ge::DataType data_type{ge::DataType::DT_UNDEFINED};
90	};
91	
92	inline DtypePolicy PromptDtype(uint32_t index) {
93	  auto policy = DtypePolicy(index);
