137	    return "";
138	  }
139	
140	  // 返回需要加载的头文件
141	  virtual std::vector<std::string> LoadApiHeaderFiles([[maybe_unused]] bool is_dynamic) const {
142	    return std::vector<std::string>();
143	  }
144	
145	  virtual bool IsVectorFunctionSupported(const AscNode &node) const {
146	    (void)node;
147	    return false;
148	  }
149	  virtual bool IsScalarInputSupported(const std::vector<bool> &is_scalar_list) const {
150	    (void)is_scalar_list;
151	    return false;
152	  }
153	  virtual bool IsScalarInputSupportedIfExchangeInputs(const std::vector<bool> &is_scalar_list) const {
154	    (void)is_scalar_list;
155	    return false;
156	  }
157	
158	  virtual bool IsInplaceSupported(const AscNode &node) const {
159	    (void)node;
160	    return false;
161	  }
162	
163	  virtual bool IsBrcInlineSupported(const AscNode &node) const {
164	    (void)node;
165	    return false;
166	  }
167	
168	  // 返回需要包含的头文件
169	  virtual std::vector<std::string> IncludeApiHeaderFiles() const {
170	    return {};
171	  }
172	
173	  // 如果需要插入cast节点，返回cast的目的类型
174	  virtual std::pair<std::vector<ge::DataType>, std::vector<ge::DataType>> GetConversionDtype(const AscNode &node) {
175	    std::pair<std::vector<ge::DataType>, std::vector<ge::DataType>> conversion_dtype;
176	    AscNodeInputs node_inputs = node.inputs;
177	    AscNodeOutputs node_outputs = node.outputs;
178	    for (size_t i = 0; i < node_inputs().size(); i++) {
179	      conversion_dtype.first.emplace_back(node_inputs[i].attr.dtype);
180	    }
181	    for (size_t i = 0; i < node_outputs().size(); i++) {
182	      conversion_dtype.second.emplace_back(node_outputs[i].attr.dtype);
183	    }
184	    return conversion_dtype;
185	  }
