284	inline std::string UpdateViewIfCrossLoop(const std::string &trans_infos, const std::string &input_api_sched_axis,
285	                                         const std::string &op_attr_sched_axis, const std::string &tie_expression) {
286	  return "AxisUtils::UpdateViewIfCrossLoop(" + trans_infos + ", " + input_api_sched_axis + ", " + op_attr_sched_axis +
287	         ", " + "std::move(" + tie_expression + "))";
288	}
289	
290	inline void GenChosenInputView(const AscIrDef &def, const uint32_t chosen_input_index, std::stringstream &ss) {
291	  const auto &input_defs = def.GetInputDefs();
292	  ss << input_defs[chosen_input_index].first + "_tmp = " << "{*" << input_defs[chosen_input_index].first
293	     << "_in.axis, *" << input_defs[chosen_input_index].first << "_in.repeats, *"
294	     << input_defs[chosen_input_index].first << "_in.strides};" << std::endl;
295	}
296	template <class Policy>
297	void GenErrorIfPolicyInvalid(Policy policy, size_t range, std::stringstream &ss) {
298	  if (policy.use_input_index < range) {
299	    return;
300	  }
301	  ss << "Policy is invalid as use_input_index :" << policy.use_input_index
302	     << " should be less than input size:" << range << std::endl;
303	}
304	
305	inline void DefineChosenInputView(const AscIrDef &def, const ViewPolicy &policy, uint32_t &chosen_input_index,
306	                                  std::unordered_set<uint32_t> &chosen_input_index_set, std::stringstream &ss) {
307	  const auto &input_defs = def.GetInputDefs();
308	  ss << "  // set tmp view to store input view and apply view transform" << std::endl;
309	  const std::string view_type("View ");
310	  GenErrorIfPolicyInvalid(policy, input_defs.size(), ss);
311	  chosen_input_index = policy.use_input_index;
312	  ss << "  ";
313	  if (chosen_input_index_set.insert(chosen_input_index).second) {
314	    ss << view_type;
315	  }
316	  GenChosenInputView(def, chosen_input_index, ss);
317	}
