319	inline void SameDataTypeFromInput(const AscIrDef &def, std::stringstream &ss, const char *input_name) {
320	  const auto &output_defs = def.GetOutputDefs();
321	  for (const auto &output_def : output_defs) {
322	    ss << "  op." << output_def.first << ".dtype = static_cast<ge::DataType>(" << input_name << "_in.dtype);"
323	       << std::endl;
324	  }
325	}
326	
327	inline void GenerateViewUpdateCode(const AscIrDef &def, const std::pair<size_t, size_t> out_to_chosen_input,
328	                                   const ApplyOutputView &apply_output_view, std::stringstream &ss,
329	                                   bool &gen_trans_infos_instance) {
330	  const auto &input_defs = def.GetInputDefs();
331	  const auto &output_defs = def.GetOutputDefs();
332	  const size_t output_index = out_to_chosen_input.first;
333	  const size_t chosen_input_index = out_to_chosen_input.second;
334	  if (!gen_trans_infos_instance) {
335	    ss << "  auto trans_infos = CodeGenUtils::GetOwnerGraphAscAttr(op." << output_defs[output_index].first
336	       << ".GetOwnerOp())" << "->trans_info_road;" << std::endl;
337	    gen_trans_infos_instance = true;
338	  }
339	
340	  const std::string which_input_api_sched_axis = output_defs[output_index].first + "_in_api_sched_axis";
341	  ss << "  auto " << which_input_api_sched_axis << " = CodeGenUtils::GetOwnerOpAscAttr("
342	     << input_defs[chosen_input_index].first << "_in.GetOwnerOp())"
343	     << "->sched.axis;" << std::endl;
344	  std::string view = input_defs[chosen_input_index].first + "_tmp";
345	  ss << "  {" << std::endl << "    const auto &[axes, repeats, strides] = ";
346	  std::string val =
347	      UpdateViewIfCrossLoop("trans_infos", which_input_api_sched_axis, "op.attr.sched.axis", view).append(".second");
348	  // 应用输出的语义变换
349	  if (!(apply_output_view == nullptr)) {
350	    ss << apply_output_view(val) << ";" << std::endl;
351	  } else {
352	    ss << val << ";" << std::endl;
353	  }
354	  ss << "    std::tie(*op." << output_defs[output_index].first << ".axis, *op." << output_defs[output_index].first
355	     << ".repeats, *op." << output_defs[output_index].first << ".strides) = std::make_tuple(axes, repeats, strides);"
356	     << std::endl
357	     << "  }" << std::endl;
358	}
359	
360	inline ApplyOutputView GenApplyOutputViewFunc(const AscIrDef &def, const size_t output_index,
361	                                              uint32_t &chosen_input_index, std::stringstream &ss) {
362	  (void)chosen_input_index;
363	  const auto &output_views_policy = def.GetViewPolicy();
364	  const auto &policy = output_views_policy[output_index];
365	  ApplyOutputView apply_output_view;
366	  switch (policy.view_type) {
367	    case ViewPolicy::kElementWise:
368	      break;
369	    case ViewPolicy::kReduce:
370	      if (!def.IsAttrExisted(policy.reduce_axis_attr_name)) {
371	        return apply_output_view;
372	      }
373	      apply_output_view = [&output_views_policy, output_index](const std::string &var) -> std::string {
374	        return "AxisUtils::ReduceView(" + var + ", " + output_views_policy[output_index].reduce_axis_attr_name + ")";
375	      };
376	      break;
377	    case ViewPolicy::kBroadCast:  // TODO 广播代码后续支持
378	    case ViewPolicy::kInvalid:
379	    default:
380	      ss << "unsupported policy type: " << policy.view_type << std::endl;
381	      break;
382	  }
383	  return apply_output_view;
384	}
385	
386	inline void InferViewByPolicy(const AscIrDef &def, std::stringstream &ss) {
387	  const auto &output_defs = def.GetOutputDefs();
388	  const auto &output_views_policy = def.GetViewPolicy();
389	  if (output_defs.size() != output_views_policy.size()) {
390	    std::string error_info = std::string("view_policy's size ")
391	                                 .append(std::to_string(output_views_policy.size()))
392	                                 .append(" should be equal with output_defs's size ")
393	                                 .append(std::to_string(output_defs.size()));
394	    ss << error_info;
395	    return;
396	  }
397	  bool gen_trans_infos_instance = false;
398	  std::unordered_set<uint32_t> chosen_input_index_set;
399	  for (size_t output_index = 0U; output_index < output_views_policy.size(); ++output_index) {
400	    uint32_t chosen_input_index = 0U;
401	    DefineChosenInputView(def, output_views_policy[output_index], chosen_input_index, chosen_input_index_set, ss);
402	    GenerateViewUpdateCode(def, std::make_pair(output_index, chosen_input_index),
403	                           GenApplyOutputViewFunc(def, output_index, chosen_input_index, ss), ss,
404	                           gen_trans_infos_instance);
405	  }
406	}
407	
408	inline void InferDtypeByPolicy(const AscIrDef &def, std::stringstream &ss) {
409	  const auto &output_defs = def.GetOutputDefs();
410	  const auto &output_dtypes_policy = def.GetOutputDtypePolicy();
411	  if (output_defs.size() != output_dtypes_policy.size()) {
412	    std::string error_info = std::string("dtype_policy's size ")
413	                                 .append(std::to_string(output_dtypes_policy.size()))
414	                                 .append("should be equal with output_defs's size ")
415	                                 .append(std::to_string(output_defs.size()));
416	    ss << error_info;
417	    return;
418	  }
419	  const auto &input_defs = def.GetInputDefs();
420	  for (size_t output_index = 0U; output_index < output_dtypes_policy.size(); ++output_index) {
421	    const auto &policy = output_dtypes_policy[output_index];
422	    switch (policy.policy_type) {
423	      case DtypePolicy::kUseInput:
424	        GenErrorIfPolicyInvalid(policy, input_defs.size(), ss);
425	        ss << "  op." << output_defs[output_index].first << ".dtype = static_cast<ge::DataType>("
426	           << input_defs[policy.use_input_index].first << "_in.dtype);" << std::endl;
427	        break;
428	      case DtypePolicy::kPromptInput:
429	        GenErrorIfPolicyInvalid(policy, input_defs.size(), ss);
430	        ss << "  op." << output_defs[output_index].first
431	           << ".dtype = DtypeTransformUtils::Prompt(static_cast<ge::DataType>("
432	           << input_defs[policy.use_input_index].first << "_in.dtype));" << std::endl;
433	        break;
434	      case DtypePolicy::kUseDtype:
435	        ss << "  op." << output_defs[output_index].first << ".dtype = static_cast<ge::DataType>(" << policy.data_type
436	           << ");" << std::endl;
437	        break;
438	      case DtypePolicy::kInvalid:
439	      default:
440	        ss << "unsupported policy type: " << policy.policy_type << std::endl;
441	    }
442	  }
443	}
444	
445	inline void SameDataTypeFromFirstInput(const AscIrDef &def, std::stringstream &ss) {
